solution:
type Color = {
  r: Int;
  g: Int;
  b: Int;
}

fn Color.brightness(self) -> Int {
  return (r + g + b) / 3;
}

fn Color.is_dark(self) -> Bool {
  return self.brightness() < 128;
}

fn Color.to_hex(self) -> Str {
  let hex = "0123456789ABCDEF";
  return "#" + hex + hex + hex + hex + hex + hex;
}

fn main() -> Int {
  let crimson = Color{ r: 220; g: 20; b: 60; };
  if crimson.is_dark() { return 1; }
  return 0;
}
